alter table gov_repo.ict_incidents add column if not exists recovery_status gov_repo.recovery_status not null default 'not_started',add column if not exists eradication_started_at timestamptz,add column if not exists eradication_completed_at timestamptz,add column if not exists recovery_started_at timestamptz,add column if not exists recovery_completed_at timestamptz,add column if not exists monitoring_started_at timestamptz,add column if not exists monitoring_ends_at timestamptz,add column if not exists rto_target_minutes integer,add column if not exists rpo_target_minutes integer,add column if not exists rto_actual_minutes integer generated always as (case when recovery_completed_at is not null and occurred_at is not null then extract(epoch from (recovery_completed_at-occurred_at))::integer/60 else null end) stored,add column if not exists rto_breach boolean generated always as (case when rto_target_minutes is not null and recovery_completed_at is not null and occurred_at is not null then (extract(epoch from (recovery_completed_at-occurred_at))/60)>rto_target_minutes else false end) stored,add column if not exists data_loss_minutes integer,add column if not exists rpo_breach boolean generated always as (case when rpo_target_minutes is not null and data_loss_minutes is not null then data_loss_minutes>rpo_target_minutes else false end) stored,add column if not exists remediation_actions jsonb not null default '[]',add column if not exists remediation_evidence_id uuid references gov_repo.evidence(evidence_id),add column if not exists workaround_applied boolean not null default false,add column if not exists permanent_fix_applied boolean not null default false,add column if not exists permanent_fix_date date;
alter table gov_repo.ict_incidents add column if not exists involves_ai_system boolean not null default false,add column if not exists primary_ai_system_id uuid references gov_repo.ai_systems(system_id),add column if not exists ai_serious_incident_id uuid,add column if not exists ai_act_reporting_required boolean not null default false,add column if not exists pii_data_exposed boolean not null default false,add column if not exists phi_data_exposed boolean not null default false,add column if not exists financial_data_exposed boolean not null default false,add column if not exists gdpr_breach_notified boolean not null default false,add column if not exists gdpr_breach_ref varchar(100),add column if not exists dpa_notification_deadline timestamptz;
alter table gov_repo.ict_incidents add column if not exists involves_third_party boolean not null default false,add column if not exists primary_provider_id uuid references gov_repo.third_party_providers(provider_id),add column if not exists provider_sla_breach boolean not null default false,add column if not exists provider_incident_ref varchar(100),add column if not exists subcontractor_involved boolean not null default false,add column if not exists concentration_risk_flag boolean not null default false;
alter table gov_repo.ict_incidents add column if not exists direct_financial_loss_eur numeric(15,2),add column if not exists indirect_financial_loss_eur numeric(15,2),add column if not exists regulatory_fine_risk_eur numeric(15,2),add column if not exists reputational_cost_eur numeric(15,2),add column if not exists business_impact_summary text,add column if not exists operations_affected text[],add column if not exists sla_breaches_to_clients boolean not null default false,add column if not exists client_notifications_required boolean not null default false,add column if not exists client_notifications_sent_at timestamptz,add column if not exists cyber_insurance_claim_raised boolean not null default false,add column if not exists cyber_insurance_ref varchar(100);;
